-- Initial Nakpri catalogue (10 launch hardware & accessory products). Safe to re-run.
insert into public.products
  (slug, name, category, price, original_price, description, details, delivery, sizes,
   is_featured, is_bestseller, stock_quantity, image_url, sort_order)
values
  ('macbook-air-m2', 'Apple MacBook Air 13.6" M2 (Midnight)', 'Laptops', 12500, 13800, 'Apple M2 chip with 8-core CPU and 8-core GPU, 16GB unified memory, 256GB SSD storage. Liquid Retina display with True Tone, 1080p FaceTime HD camera, and MagSafe 3 charging.', '13.6-inch Liquid Retina display. 16GB Unified RAM, 256GB SSD. Backlit Magic Keyboard with Touch ID. Battery life up to 18 hours. 1-year warranty.', 'Same-day express dispatch in Greater Accra. Insured delivery across Ghana.', array['16GB / 256GB SSD', '16GB / 512GB SSD'], true, true, 12, '/images/product-macbook-air-m2.jpg', 0),
  ('thinkpad-x1-carbon-gen11', 'Lenovo ThinkPad X1 Carbon Gen 11', 'Laptops', 16800, 18500, 'Ultra-light business powerhouse with Intel Core i7 13th Gen, 16GB LPDDR5, 512GB PCIe Gen4 SSD, and 14-inch WUXGA IPS anti-glare display.', 'Intel Core i7-1355U (up to 5.0 GHz). 16GB LPDDR5-6400MHz. 512GB NVMe SSD. Carbon-fiber chassis at 1.12kg. Spill-resistant keyboard.', 'Express delivery within 24-48 hours across Ghana. Official Lenovo distributor warranty.', array['i7 / 16GB / 512GB', 'i7 / 32GB / 1TB'], true, true, 8, '/images/product-thinkpad-x1-carbon.jpg', 1),
  ('dell-xps-15-oled', 'Dell XPS 15 (9530) OLED Touch', 'Laptops', 21500, 23000, 'Intel Core i7 13th Gen, NVIDIA GeForce RTX 4060, 32GB DDR5, 1TB SSD. 15.6-inch 3.5K OLED InfinityEdge touch display for creators and pro developers.', 'Intel Core i7-13700H, 14-core. 32GB DDR5 4800MHz. NVIDIA RTX 4060 8GB GDDR6. 3.5K (3456x2160) OLED Touch. CNC aluminum body.', 'Complimentary white-glove delivery in Greater Accra. Standard shipping nationwide.', array['i7 / 32GB / 1TB RTX 4060'], true, false, 5, '/images/product-dell-xps-15.jpg', 2),
  ('hp-envy-x360-14', 'HP Envy x360 2-in-1 Convertible', 'Laptops', 9800, 10800, 'Versatile touchscreen 2-in-1 laptop with AMD Ryzen 7 7730U, 16GB RAM, 512GB NVMe SSD, and 360-degree hinge for laptop, tent, and tablet modes.', 'AMD Ryzen 7 7730U 8-core processor. 16GB onboard memory. 512GB M.2 SSD. 14-inch FHD Touchscreen. Stylus compatible.', 'Express 24-hour delivery in Greater Accra. Free screen protector included.', array['Ryzen 7 / 16GB / 512GB SSD'], true, false, 14, '/images/product-hp-envy-x360.jpg', 3),
  ('dell-ultrasharp-27-4k', 'Dell UltraSharp 27" 4K USB-C Hub Monitor (U2723QE)', 'Monitors', 6800, null, 'IPS Black technology with 2000:1 contrast ratio, 98% DCI-P3, 4K UHD 3840x2160. Built-in USB-C hub with 90W power delivery, RJ45 Ethernet, and daisy-chaining.', '27" 4K UHD (3840x2160) @ 60Hz. USB-C 90W PD, HDMI, DisplayPort, RJ45. Tilt, swivel, pivot, and height adjustable stand.', 'Insured transit across Ghana. Same-day delivery in Accra.', null, true, true, 9, '/images/product-dell-ultrasharp-27.jpg', 4),
  ('samsung-t7-shield-2tb', 'Samsung T7 Shield 2TB Portable Rugged SSD', 'Storage', 2200, 2500, 'Rugged durability with IP65 dust and water resistance, up to 1,050 MB/s read and 1,000 MB/s write speeds via USB 3.2 Gen 2. Shock-resistant elastomeric outer shell.', '2TB capacity. USB 3.2 Gen 2 (10Gbps). IP65 rated, 3-meter drop resistance. Hardware AES 256-bit encryption. Includes Type-C to C and Type-C to A cables.', 'Same-day express delivery in Greater Accra. 48 hours nationwide.', array['1TB', '2TB', '4TB'], true, true, 25, '/images/product-samsung-t7-shield.jpg', 5),
  ('logitech-mx-master-3s', 'Logitech MX Master 3S Wireless Performance Mouse', 'Peripherals', 1350, null, 'Quiet clicks, 8,000 DPI track-on-glass sensor, and MagSpeed electromagnetic scrolling. Flow cross-computer control and USB-C quick recharge.', 'Darkfield 8000 DPI sensor. MagSpeed scroll wheel (1,000 lines/sec). 70 days battery life. Multi-device Bluetooth & Logi Bolt.', 'Same-day delivery in Accra. Free delivery when bundled with any laptop.', null, true, true, 30, '/images/product-logitech-mx-master-3s.jpg', 6),
  ('keychron-k2-pro-wireless', 'Keychron K2 Pro QMK/VIA Wireless Mechanical Keyboard', 'Peripherals', 1450, 1650, 'Compact 75% layout custom wireless mechanical keyboard with hot-swappable switches, sound-absorbing foam, double-shot PBT keycaps, and Mac & Windows layout support.', '75% layout, 84 keys. Hot-swappable Keychron K Pro Red/Brown switches. Bluetooth 5.1 & Type-C wired. RGB backlighting, 4000mAh battery.', 'Express delivery across Greater Accra & Ghana nationwide.', array['Red Switch (Linear)', 'Brown Switch (Tactile)'], false, true, 18, '/images/product-keychron-k2-pro.jpg', 7),
  ('anker-thunderbolt-4-dock', 'Anker PowerExpand 5-in-1 Thunderbolt 4 Mini Dock', 'Accessories', 2100, null, 'Thunderbolt 4 upstream port with 85W laptop charging, three Thunderbolt 4 downstream ports (40Gbps, 15W power), and one USB-A 3.1 Gen 2 port. Supports single 8K or dual 4K displays.', '40Gbps data transfer. 85W host charging. Supports dual 4K@60Hz or single 8K@30Hz. Over-current and temperature protection.', 'Express 24-hour delivery in Greater Accra.', null, true, false, 10, '/images/product-anker-thunderbolt-dock.jpg', 8),
  ('sony-wh-1000xm5', 'Sony WH-1000XM5 Wireless Noise-Cancelling Headphones', 'Audio', 4200, 4600, 'Industry-leading noise cancellation with two processors and 8 microphones. Exceptional sound quality with LDAC, crystal clear hands-free calling, and up to 30-hour battery.', 'Auto NC Optimizer. 30mm carbon fiber driver. Speak-to-chat & multipoint Bluetooth. 3-min quick charge gives 3 hours playback. Carrying case included.', 'Express insured dispatch across Ghana.', array['Black', 'Silver'], true, true, 12, '/images/product-sony-wh1000xm5.jpg', 9)
on conflict (slug) do nothing;
